SELECT DISTINCT ?zone ?class ?label WHERE {
  ?zone a ?class .
  FILTER(str(?zone) CONTAINS "Zone_F3_Z01" || str(?label) CONTAINS "Core_mid")
  OPTIONAL{ ?zone rdfs:label ?label }
}

SELECT ?p ?class ?label ?ts ?ext WHERE {
  ?p ref:hasTimeseriesId ?ts .
  OPTIONAL{ ?p ref:hasExternalReference ?ext }
  OPTIONAL{ ?p rdfs:label ?label }
  ?p a ?class .
} LIMIT 200

SELECT ?s ?class ?label WHERE {
  ?s a brick:ZoneTemperatureSensor .
  OPTIONAL{ ?s rdfs:label ?label }
}

SELECT ?s ?class ?label WHERE {
  ?s a/brick:hasSubclass ?class .
  ?s brick:hasProperty|brick:pointType|brick:isLocatedAt ?p ;
     OPTIONAL{ ?s rdfs:label ?label }
} LIMIT 0

